from pathlib import Path
from PIL import Image,ImageDraw
import json
R=Path(__file__).resolve().parents[1];O=R/'art/studies/coliseum-132';P='/art/studies/coliseum-132/'
labels=[v for v in ['selected','0x','2x','5x','10x'] if (O/v/'main-4k.png').exists()];roi=(1400,730,2510,1330)
for label in labels:
 d=O/label;im=Image.open(d/'main-4k.png').convert('RGB');im.resize((1440,1082),Image.Resampling.LANCZOS).save(d/'main.png');im.crop(roi).save(d/'street.png');im.crop(roi).convert('L').save(d/'gray.png')
